struct Derived : Base { int x = 7; };
try {
    throw Derived{};
} catch (const Base& b) {
    // 此处 b 指向什么？
}
```
关于 `b` 的说法正确的是？

```cpp
struct Base { virtual ~Base() = default; };
struct Derived : Base {};
int main() {
    try {
        throw Derived{};
    } catch (const Base&) {
    } catch (const Derived&) {
    }
}
```
