```cpp
struct Base { virtual ~Base() = default; };
struct Derived : Base { int extra = 1; };
int main() {
    Derived d;
    Base* p = &d;
    try {
        throw *p;
    } catch (const Derived&) {
    } catch (const Base&) {
    }
}
```
实际进入哪个处理器？

